data["466"] = [
 {"title":"Open cloze (avançado) — Orações participiais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"___ on years of disciplined calculation, our credibility with the board now rests on solid ground.","a":"Built"},
   {"q":"___ quietly for a decade, the discipline has hardened into genuine credibility.","a":"Done / Practised"},
   {"q":"___ the effective rate against the statutory rate, the team uncovered a material variance.","a":"Reconciling / Comparing"},
   {"q":"The figures, ___ traced back to source, held up under the auditor's scrutiny.","a":"having been"},
   {"q":"___ from a single, reconciled ledger, the return required no last-minute correction.","a":"Prepared / Drawn"},
   {"q":"___ confidence in the numbers, every strategic conversation becomes markedly easier.","a":"Having built"},
   {"q":"The calculation, ___ documented at each step, withstood reconstruction years later.","a":"carefully"},
   {"q":"___ left unreconciled, even a minor difference can cause the whole position to wobble.","a":"If / Once"},
   {"q":"___ that the rate held up, the director presented it to the committee without hesitation.","a":"Knowing / Confident"},
   {"q":"The discipline, ___ unglamorous, is precisely what underpins executive trust.","a":"though / albeit"}]},
 {"title":"Key word transformation — mantenha o sentido (orações participiais)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"Because it was built on discipline, the trust held.  ·  (BUILT)  ·  ___ discipline, the trust held.","a":"Built on"},
   {"q":"After we had reconciled the figures, we filed the return.  ·  (HAVING)  ·  ___ the figures, we filed the return.","a":"Having reconciled"},
   {"q":"When it is left unreconciled, the figure wobbles.  ·  (LEFT)  ·  ___, the figure wobbles.","a":"Left unreconciled"},
   {"q":"Since we knew the rate held up, we presented it.  ·  (KNOWING)  ·  ___ held up, we presented it.","a":"Knowing the rate"},
   {"q":"The discipline, although it is unglamorous, builds trust.  ·  (THOUGH)  ·  Though ___, it builds trust.","a":"unglamorous, the discipline"},
   {"q":"As it was traced to source, the figure held up.  ·  (TRACED)  ·  ___ to source, the figure held up.","a":"Traced back"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (orações participiais)","note":"Reescreva em registro formal usando oração participial.","items":[
   {"q":"Because the discipline was practised quietly for years, it became credibility.","a":"Practised quietly for years, the discipline hardened into credibility."},
   {"q":"After we built confidence in the numbers, everything got easier.","a":"Having built confidence in the numbers, every conversation became easier."},
   {"q":"When you leave a difference unreconciled, the position wobbles.","a":"Left unreconciled, even a minor difference causes the position to wobble."},
   {"q":"Since the figures could be traced to source, they survived the audit.","a":"Traceable to source, the figures withstood the auditor's scrutiny."},
   {"q":"We compared the two rates and found a big variance.","a":"Comparing the effective rate against the statutory rate, we uncovered a material variance."},
   {"q":"The work isn't glamorous, but it builds trust.","a":"Unglamorous though it is, the work is precisely what builds trust."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (orações participiais)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Build on discipline, the trust held over time.","a":"Built on discipline, the trust held over time. (oração participial passiva usa particípio 'Built')"},
   {"q":"Having reconcile the figures, we filed the return.","a":"Having reconciled the figures, we filed the return. ('having' + particípio passado)"},
   {"q":"Comparing the two rates, a variance was uncovered by us.","a":"Comparing the two rates, we uncovered a variance. (o sujeito da participial deve ser o sujeito da oração principal)"},
   {"q":"Leaving unreconciled, the difference caused a wobble.","a":"Left unreconciled, the difference caused a wobble. (sentido passivo exige particípio passado 'Left')"},
   {"q":"Knowing that held up, the director presented the rate.","a":"Knowing the rate held up, the director presented it. (falta o objeto 'the rate' na participial)"},
   {"q":"Traced to source, the auditor accepted the figures.","a":"Traced to source, the figures were accepted by the auditor. (sujeito da participial deve ser 'the figures', não 'the auditor')"}]},
 {"title":"Advanced collocations & lexis — disciplina do cálculo tributário (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to trace a figure back to source","a":"rastrear um número até a origem"},{"q":"to withstand scrutiny","a":"resistir ao escrutínio"},
   {"q":"a defensible audit trail","a":"uma trilha de auditoria defensável"},{"q":"to reconcile to the ledger","a":"conciliar com o razão"},
   {"q":"to hold up under reconstruction","a":"sustentar-se sob reconstrução"},{"q":"a material variance","a":"uma variação material"},
   {"q":"to bed in a discipline","a":"consolidar uma disciplina"},{"q":"to underpin credibility","a":"sustentar a credibilidade"},
   {"q":"to tie out the numbers","a":"fechar os números"},{"q":"a single source of truth","a":"uma fonte única de verdade"}]},
 {"title":"Discuss / Argue — orações participiais no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why does disciplined calculation matter beyond the number itself?","a":"Done quietly and consistently for years, disciplined calculation hardens into the credibility on which every difficult conversation with the board ultimately depends."},
   {"q":"How do you ensure a tax figure survives later challenge?","a":"Traced back to source and reconciled to the ledger, our figures are designed to hold up under reconstruction long after the period has closed."},
   {"q":"What happens when a difference is left unaddressed?","a":"Left unreconciled, even a trivial difference can, over time, cause an otherwise sound position to wobble under scrutiny."},
   {"q":"How does calculation discipline change strategic conversations?","a":"Having built unimpeachable confidence in the numbers, I find that every strategic conversation proceeds from a position of trust rather than doubt."},
   {"q":"Why is unglamorous work worth defending to leadership?","a":"Unglamorous though it is, the daily discipline of reconciliation is precisely what spares us the far costlier emergencies of restatement."},
   {"q":"How do you present a variance to the committee?","a":"Comparing the effective rate against the statutory rate, I present the variance with its full derivation, so that the committee sees not merely the number but its provenance."}]}
]

