data["467"] = [
 {"title":"Open cloze (avançado) — Sintagmas nominais abstratos (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"The ___ between the marginal and the effective rate is poorly understood at board level.","a":"distinction"},
   {"q":"The ___ of every investment decision turns on the rate applied to the next pound earned.","a":"quality"},
   {"q":"The ___ of the discipline is itself its greatest virtue: one rate, one rule, applied consistently.","a":"simplicity"},
   {"q":"The ___ of rates through the brackets reflects a society's choices about fairness.","a":"progression"},
   {"q":"It is the ___ of the marginal rate to investment that executives most often overlook.","a":"relevance"},
   {"q":"The ___ of the two rates in casual conversation is a persistent source of error.","a":"confusion / conflation"},
   {"q":"The ___ of the effective rate to investors must be handled with care.","a":"communication"},
   {"q":"The ___ of marginal thinking lies in its application to the very next decision.","a":"power / value"},
   {"q":"The ___ of the average rate gives the overall picture, but it conceals the margin.","a":"calculation"},
   {"q":"The pedant's ___ on the distinction can, in this instance, be wholly justified.","a":"insistence"}]},
 {"title":"Key word transformation — mantenha o sentido (sintagmas abstratos)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"It matters how we distinguish marginal from effective.  ·  (DISTINCTION)  ·  The ___ matters.","a":"distinction between marginal and effective"},
   {"q":"The discipline is simple, and that is its virtue.  ·  (SIMPLICITY)  ·  The ___ is its virtue.","a":"simplicity of the discipline"},
   {"q":"Rates progress through the brackets.  ·  (PROGRESSION)  ·  The ___ reflects fairness.","a":"progression of rates"},
   {"q":"People confuse the two rates constantly.  ·  (CONFUSION)  ·  The ___ is a source of error.","a":"confusion of the two rates"},
   {"q":"We must communicate the effective rate carefully.  ·  (COMMUNICATION)  ·  The ___ demands care.","a":"communication of the effective rate"},
   {"q":"The decision is only as good as the rate we apply.  ·  (QUALITY)  ·  The ___ turns on the rate.","a":"quality of the decision"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (sintagmas abstratos)","note":"Reescreva em registro formal usando substantivos abstratos.","items":[
   {"q":"People mix up the marginal and effective rates all the time.","a":"The conflation of the marginal and effective rates is a persistent source of error."},
   {"q":"How good a decision is depends on the rate you apply to it.","a":"The quality of every decision turns on the rate applied at the margin."},
   {"q":"The nice thing about this rule is that it's simple.","a":"The simplicity of the discipline is, in itself, its principal virtue."},
   {"q":"Rates go up as you move through the brackets.","a":"The progression of rates through the brackets reflects deliberate policy choices."},
   {"q":"We have to be careful how we explain the effective rate to investors.","a":"The communication of the effective rate to investors demands considerable care."},
   {"q":"The marginal rate is what really drives whether you invest.","a":"It is the relevance of the marginal rate to investment that executives most often underappreciate."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (sintagmas abstratos)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"The distinction among the marginal and effective rate is unclear.","a":"The distinction between the marginal and effective rate is unclear. ('distinction between', não 'among', para dois itens)"},
   {"q":"The simpleness of the discipline is its virtue.","a":"The simplicity of the discipline is its virtue. (substantivo abstrato correto: 'simplicity')"},
   {"q":"The progression of rates reflect society's choices.","a":"The progression of rates reflects society's choices. (núcleo singular 'progression' → 'reflects')"},
   {"q":"The confusing of the two rates causes errors.","a":"The confusion of the two rates causes errors. (substantivo abstrato: 'confusion')"},
   {"q":"The relevance of marginal thinking to investment are overlooked.","a":"The relevance of marginal thinking to investment is overlooked. (núcleo singular 'relevance' → 'is')"},
   {"q":"The communication the effective rate demands care.","a":"The communication of the effective rate demands care. (falta 'of' no sintagma)"}]},
 {"title":"Advanced collocations & lexis — pensamento marginal e de alíquotas (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"at the margin","a":"na margem"},{"q":"the next pound earned","a":"a próxima libra ganha"},
   {"q":"to bracket-creep","a":"sofrer com o avanço de faixa"},{"q":"a blended rate","a":"uma alíquota combinada"},
   {"q":"to benchmark against peers","a":"comparar com os pares"},{"q":"the incidence of tax","a":"a incidência do tributo"},
   {"q":"a step change in the rate","a":"um salto na alíquota"},{"q":"to be rate-sensitive","a":"ser sensível à alíquota"},
   {"q":"the marginal pound of profit","a":"a libra marginal de lucro"},{"q":"a headline-versus-effective gap","a":"a diferença nominal-efetiva"}]},
 {"title":"Discuss / Argue — sintagmas abstratos no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Why does the marginal–effective distinction matter for decisions?","a":"The distinction between the marginal and the effective rate is, to my mind, decisive, since it is the marginal rate that governs the quality of the very next investment decision."},
   {"q":"How do you guard against confusing the two rates?","a":"The conflation of the two rates is so common that I insist on their separation in every memo, however pedantic the insistence may appear."},
   {"q":"How do you communicate the effective rate to investors?","a":"The communication of the effective rate to investors demands a care that reflects the gap between what is paid and what is reported."},
   {"q":"What is the virtue of a simple rate discipline?","a":"The simplicity of the discipline is precisely its strength, for a rule that everyone understands is a rule that everyone applies consistently."},
   {"q":"How does marginal thinking inform a sourcing or hiring decision?","a":"The relevance of the marginal rate is most acute at the point of an additional hire or a price increase, where the next pound's treatment tips the balance."},
   {"q":"When is pedantry about rates justified?","a":"The pedant's insistence on the distinction is wholly warranted whenever a misread rate would steer capital toward the wrong decision."}]}
]

