data["468"] = [
 {"title":"Open cloze (avançado) — Construções passivas formais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Costs are ___ where they make genuine economic sense, not where they minimise tax.","a":"booked"},
   {"q":"Revenue is ___ by the entity that genuinely earns it, in line with substance.","a":"recognised"},
   {"q":"The taxable base is ___ through the application of allowable deductions.","a":"adjusted / reduced"},
   {"q":"Management fees are ___ across entities on a defensible economic basis.","a":"allocated"},
   {"q":"Timing differences are ___ so that the effective rate reflects economic reality.","a":"recognised / accounted for"},
   {"q":"The boundary between sound and aggressive planning is ___ by substance, not by intent alone.","a":"determined / defined"},
   {"q":"Where value is created, profit ought to ___ recognised — that is the governing principle.","a":"be"},
   {"q":"Deductions are ___ only where the underlying expenditure is genuinely incurred.","a":"claimed"},
   {"q":"The structure was ___ to withstand challenge, not merely to lower the headline rate.","a":"designed"},
   {"q":"Each adjustment must ___ supported by contemporaneous documentation.","a":"be"}]},
 {"title":"Key word transformation — mantenha o sentido (passiva formal)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We book costs where they make economic sense.  ·  (BOOKED)  ·  Costs ___ where they make sense.","a":"are booked"},
   {"q":"The entity that earns the revenue recognises it.  ·  (RECOGNISED)  ·  Revenue ___ by the entity that earns it.","a":"is recognised"},
   {"q":"We allocate management fees on a defensible basis.  ·  (ALLOCATED)  ·  Management fees ___ on a defensible basis.","a":"are allocated"},
   {"q":"We adjusted the base by applying deductions.  ·  (ADJUSTED)  ·  The base ___ through deductions.","a":"was adjusted"},
   {"q":"Substance determines the boundary, not intent.  ·  (DETERMINED)  ·  The boundary ___ by substance.","a":"is determined"},
   {"q":"We designed the structure to withstand challenge.  ·  (DESIGNED)  ·  The structure ___ to withstand challenge.","a":"was designed"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passiva formal)","note":"Reescreva em registro formal usando passiva.","items":[
   {"q":"We put costs where they actually make sense.","a":"Costs are booked where they make genuine economic sense."},
   {"q":"Whoever really earns the revenue should book it.","a":"Revenue is recognised by the entity that genuinely earns it."},
   {"q":"We tweaked the numbers to bring the tax bill down.","a":"The taxable base was adjusted through the application of allowable deductions."},
   {"q":"We split the management fees fairly across the group.","a":"Management fees are allocated across entities on a defensible economic basis."},
   {"q":"What makes planning OK or not is substance, not what you meant.","a":"The boundary between sound and aggressive planning is determined by substance rather than intent."},
   {"q":"We built the structure so it could survive a challenge.","a":"The structure was designed to withstand challenge rather than merely to reduce the headline rate."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passiva formal)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Costs are book where they make economic sense.","a":"Costs are booked where they make economic sense. (passiva exige particípio 'booked')"},
   {"q":"Revenue is recognise by the entity that earns it.","a":"Revenue is recognised by the entity that earns it. (particípio: 'recognised')"},
   {"q":"Management fees is allocated across entities.","a":"Management fees are allocated across entities. (sujeito plural exige 'are')"},
   {"q":"The structure was designed for withstand challenge.","a":"The structure was designed to withstand challenge. ('designed to' + infinitivo)"},
   {"q":"The base was adjusted by the application allowable deductions.","a":"The base was adjusted through the application of allowable deductions. (falta 'of'; 'through' soa mais formal aqui)"},
   {"q":"Each adjustment must be support by documentation.","a":"Each adjustment must be supported by documentation. (particípio: 'supported')"}]},
 {"title":"Advanced collocations & lexis — renda tributável como alavanca (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to recognise revenue in substance","a":"reconhecer receita conforme a substância"},{"q":"to align profit with value creation","a":"alinhar lucro à criação de valor"},
   {"q":"an arm's-length basis","a":"base de plena concorrência"},{"q":"to book a cost where it is incurred","a":"contabilizar custo onde incorrido"},
   {"q":"to strip out a timing difference","a":"expurgar uma diferença temporária"},{"q":"to push the boundary","a":"forçar os limites"},
   {"q":"substance over form","a":"substância sobre a forma"},{"q":"to be commercially justified","a":"ter justificativa comercial"},
   {"q":"to leave a deduction on the table","a":"deixar de aproveitar uma dedução"},{"q":"a defensible allocation key","a":"um critério de rateio defensável"}]},
 {"title":"Discuss / Argue — passiva formal no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"Where should costs and revenue be recognised in your view?","a":"In my framework, costs are booked where they are genuinely incurred and revenue is recognised by the entity that truly earns it, so that the profit reported follows the value created."},
   {"q":"How do you distinguish sound from aggressive tax planning?","a":"The boundary, as I see it, is determined by substance rather than intent: a structure that is commercially justified can be defended, whereas one engineered solely for rate reduction cannot."},
   {"q":"How are inter-company fees allocated in a defensible way?","a":"Management fees are allocated on an arm's-length basis, supported by contemporaneous documentation, so that the allocation key itself would survive an authority's challenge."},
   {"q":"Why design a structure to withstand challenge rather than to minimise tax?","a":"A structure that is designed merely to lower the headline rate is fragile, whereas one built to withstand challenge protects both the saving and the reputation behind it."},
   {"q":"How should timing differences be handled in your reporting?","a":"Timing differences are recognised transparently, so that the effective rate we report reflects economic reality rather than an artefact of deferral."},
   {"q":"What governs whether a deduction is claimed?","a":"A deduction is claimed only where the underlying expenditure is genuinely incurred and documented, since an unsupported deduction is a liability dressed as a saving."}]}
]

