data["472"] = [
 {"title":"Open cloze (avançado) — Passiva com modais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Invoices must ___ checked automatically before they are allowed onto the ledger.","a":"be"},
   {"q":"Problem invoices should ___ routed out at intake, not discovered at audit.","a":"be"},
   {"q":"Records must ___ retained for the statutory period without exception.","a":"be"},
   {"q":"No incomplete invoice may ___ posted until the missing fields are supplied.","a":"be"},
   {"q":"Escalation ought ___ be triggered the moment an automated check fails.","a":"to"},
   {"q":"Documentation cannot ___ treated as a clerical afterthought; it is a governance function.","a":"be"},
   {"q":"By the time the audit began, every defective invoice should ___ been corrected.","a":"have"},
   {"q":"The intake checklist must ___ applied uniformly across every legal entity.","a":"be"},
   {"q":"Controls must be designed so that nothing defective is ___ to slip through.","a":"allowed"},
   {"q":"The issuance and retention of invoices must ___ governed as a single discipline.","a":"be"}]},
 {"title":"Key word transformation — mantenha o sentido (passiva com modais)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We must check invoices automatically.  ·  (CHECKED)  ·  Invoices must ___ automatically.","a":"be checked"},
   {"q":"You can't post an incomplete invoice.  ·  (POSTED)  ·  An incomplete invoice may not ___.","a":"be posted"},
   {"q":"We should route out problem invoices at intake.  ·  (ROUTED)  ·  Problem invoices should ___ at intake.","a":"be routed out"},
   {"q":"By audit time we should have corrected every defect.  ·  (CORRECTED)  ·  Every defect should ___ by audit time.","a":"have been corrected"},
   {"q":"We must retain records for the statutory period.  ·  (RETAINED)  ·  Records must ___ for the statutory period.","a":"be retained"},
   {"q":"We have to apply the checklist across every entity.  ·  (APPLIED)  ·  The checklist must ___ across every entity.","a":"be applied"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passiva com modais)","note":"Reescreva em registro formal usando passiva + modal.","items":[
   {"q":"We need to check every invoice automatically before it hits the ledger.","a":"Every invoice must be checked automatically before it is admitted to the ledger."},
   {"q":"Don't let incomplete invoices through until they're fixed.","a":"No incomplete invoice may be posted until the missing fields are supplied."},
   {"q":"Catch the bad invoices at the door, not in the audit.","a":"Problem invoices should be routed out at intake rather than uncovered at audit."},
   {"q":"By the time the auditor arrives, everything should already be fixed.","a":"By the time the audit commences, every defect should have been corrected."},
   {"q":"Treat documentation as governance, not paperwork.","a":"Documentation must be treated as a governance function rather than a clerical task."},
   {"q":"Keep the records for as long as the law says.","a":"Records must be retained for the full statutory period without exception."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passiva com modais)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Invoices must checked automatically.","a":"Invoices must be checked automatically. (passiva com modal exige 'be' + particípio)"},
   {"q":"Every defect should have corrected by audit time.","a":"Every defect should have been corrected by audit time. (passiva perfeita: 'have been' + particípio)"},
   {"q":"No incomplete invoice may be post until corrected.","a":"No incomplete invoice may be posted until corrected. (particípio: 'posted')"},
   {"q":"Records must be retain for the statutory period.","a":"Records must be retained for the statutory period. (particípio: 'retained')"},
   {"q":"Escalation ought be triggered when a check fails.","a":"Escalation ought to be triggered when a check fails. ('ought' exige 'to')"},
   {"q":"Nothing defective should be allowed slip through.","a":"Nothing defective should be allowed to slip through. ('allowed to' + infinitivo)"}]},
 {"title":"Advanced collocations & lexis — governança de faturas e documentos (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to route out a defect at intake","a":"barrar um defeito na entrada"},{"q":"a tax-point compliant invoice","a":"uma fatura conforme o fato gerador"},
   {"q":"to fail an automated check","a":"reprovar numa verificação automatizada"},{"q":"to retain records for the statutory period","a":"guardar documentos pelo prazo legal"},
   {"q":"an audit-ready trail","a":"uma trilha pronta para auditoria"},{"q":"to triage incoming invoices","a":"triar faturas recebidas"},
   {"q":"to bake controls into the process","a":"embutir controles no processo"},{"q":"to flag for escalation","a":"sinalizar para escalonamento"},
   {"q":"a watertight documentation regime","a":"um regime documental à prova de falhas"},{"q":"to let nothing defective slip","a":"não deixar passar nada defeituoso"}]},
 {"title":"Discuss / Argue — passiva com modais no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How should invoice quality be governed at enterprise scale?","a":"Every invoice must be checked automatically at intake, and any that fails must be routed out before it is ever admitted to the ledger."},
   {"q":"Why treat documentation as governance rather than admin?","a":"Documentation must be treated as a governance function, since it is the trail that can be reconstructed under audit, not the booking itself, on which a defence ultimately rests."},
   {"q":"What should be in place before an audit begins?","a":"By the time an audit commences, every defective invoice should already have been corrected, so that the auditor encounters a trail that is audit-ready by design."},
   {"q":"How do you ensure consistency across many entities?","a":"The intake checklist must be applied uniformly across every legal entity, for it is inconsistency, more than any single error, that auditors are trained to exploit."},
   {"q":"What is the cost of a permissive documentation regime?","a":"Where defective invoices are allowed to slip through, a clerical lapse can be transformed into a material exposure, which is why nothing defective may be posted unchecked."},
   {"q":"How do you persuade operations to invest in invoice controls?","a":"I argue that controls must be baked into the process at intake, since a defect that is caught at the door costs a fraction of one that must be unwound at audit."}]}
]

