# ---------------------------------------------------------------------------
data["473"] = [
 {"title":"Open cloze (avançado) — Orações subordinadas formais (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"___ that the CEO welcomes hard questions, the rest of the organisation learns to raise them.","a":"Provided"},
   {"q":"To the ___ that compliance is modelled at the top, it becomes a culture rather than a rule.","a":"extent"},
   {"q":"___ the figures are uncomfortable, they must still be surfaced and discussed calmly.","a":"Although / Even though"},
   {"q":"Compliance culture endures ___ long as leaders respond to doubt with patience.","a":"as / so"},
   {"q":"___ as the tone is set deliberately, the behaviour beneath it follows.","a":"In so far / Insofar"},
   {"q":"___ a difficult question is buried, the culture quietly erodes.","a":"Whenever / Once"},
   {"q":"The team raises concerns ___ that they will be met with genuine patience.","a":"on the understanding / provided"},
   {"q":"___ much depends on the tone at the top, structure alone cannot substitute for it.","a":"Inasmuch as / Given that"},
   {"q":"Doubt is surfaced calmly, ___ it might otherwise harden into concealment.","a":"lest / whereas"},
   {"q":"___ the CEO sighs at a question, the signal travels through the whole organisation.","a":"If / Should"}]},
 {"title":"Key word transformation — mantenha o sentido (subordinação formal)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"If the CEO welcomes questions, others will raise them.  ·  (PROVIDED)  ·  ___ questions, others raise them.","a":"Provided the CEO welcomes"},
   {"q":"Compliance is a culture only when modelled at the top.  ·  (EXTENT)  ·  To the ___ at the top, it is a culture.","a":"extent it is modelled"},
   {"q":"The figures are uncomfortable, but we surface them anyway.  ·  (ALTHOUGH)  ·  ___, we surface them anyway.","a":"Although the figures are uncomfortable"},
   {"q":"The team raises concerns because it trusts the response.  ·  (UNDERSTANDING)  ·  The team raises concerns on the ___.","a":"understanding it will be heard"},
   {"q":"As long as leaders are patient, the culture lasts.  ·  (SO LONG)  ·  The culture lasts ___ are patient.","a":"so long as leaders"},
   {"q":"We surface doubt so it doesn't harden into concealment.  ·  (LEST)  ·  We surface doubt ___ into concealment.","a":"lest it harden"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (subordinação formal)","note":"Reescreva em registro formal usando subordinação.","items":[
   {"q":"If the boss is open to questions, people will ask them.","a":"Provided that leadership welcomes questions, the organisation learns to raise them."},
   {"q":"Compliance is only real if the top actually models it.","a":"To the extent that compliance is modelled at the top, it becomes a genuine culture."},
   {"q":"The numbers are awkward, but we still talk about them openly.","a":"Although the figures are uncomfortable, they are nonetheless surfaced and discussed openly."},
   {"q":"The culture holds up as long as leaders stay patient.","a":"The culture endures so long as leaders respond to doubt with genuine patience."},
   {"q":"We bring doubts into the open so they don't get hidden.","a":"Doubts are surfaced openly, lest they harden into concealment."},
   {"q":"When the boss sighs at a question, everyone notices.","a":"Whenever leadership greets a question with impatience, the signal travels throughout the organisation."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (subordinação formal)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"Provided that the CEO will welcome questions, others raise them.","a":"Provided that the CEO welcomes questions, others raise them. (após 'provided that' usa-se presente, não 'will')"},
   {"q":"To the extend that it is modelled at the top, it is culture.","a":"To the extent that it is modelled at the top, it is culture. (locução correta: 'to the extent')"},
   {"q":"Although the figures are uncomfortable, but we surface them.","a":"Although the figures are uncomfortable, we surface them. ('although' e 'but' não coexistem)"},
   {"q":"The culture endures as long leaders are patient.","a":"The culture endures as long as leaders are patient. (locução: 'as long as')"},
   {"q":"We surface doubt lest it hardens into concealment.","a":"We surface doubt lest it harden into concealment. ('lest' rege subjuntivo: 'harden')"},
   {"q":"Insofar the tone is set deliberately, behaviour follows.","a":"Insofar as the tone is set deliberately, behaviour follows. (locução: 'insofar as')"}]},
 {"title":"Advanced collocations & lexis — cultura de conformidade no topo (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to set the tone at the top","a":"dar o tom a partir do topo"},{"q":"to surface a concern","a":"trazer uma preocupação à tona"},
   {"q":"to foster a speak-up culture","a":"fomentar uma cultura de fala aberta"},{"q":"to model the behaviour","a":"dar o exemplo"},
   {"q":"to greet a question with patience","a":"acolher uma pergunta com paciência"},{"q":"to drive concerns underground","a":"empurrar preocupações para a clandestinidade"},
   {"q":"a culture of candour","a":"uma cultura de franqueza"},{"q":"to embed compliance in behaviour","a":"enraizar a conformidade no comportamento"},
   {"q":"to lead by example","a":"liderar pelo exemplo"},{"q":"to bury an inconvenient truth","a":"enterrar uma verdade inconveniente"}]},
 {"title":"Discuss / Argue — subordinação formal no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How is a genuine compliance culture built?","a":"Provided that leadership welcomes hard questions and responds to doubt with patience, compliance ceases to be a rulebook and becomes a culture the organisation owns."},
   {"q":"What undermines a speak-up culture fastest?","a":"Whenever an inconvenient question is met with a sigh rather than engagement, concerns are driven underground, and the culture quietly erodes from the top down."},
   {"q":"How important is tone at the top, in your experience?","a":"To the extent that the tone is set deliberately and consistently at the top, the behaviour beneath it follows; absent that example, no procedure can substitute for it."},
   {"q":"How do you handle uncomfortable figures with the board?","a":"Although the figures are at times uncomfortable, they must be surfaced and discussed calmly, lest the discomfort of disclosure today become the crisis of concealment tomorrow."},
   {"q":"What conditions allow your team to raise concerns?","a":"My team raises concerns on the understanding that they will be met with genuine patience, which is the single condition on which candour ultimately depends."},
   {"q":"Why is leadership behaviour more powerful than policy here?","a":"Insofar as people take their cue from how leaders actually respond rather than from what the manual states, the behaviour modelled at the top is itself the policy."}]}
]

