data["476"] = [
 {"title":"Open cloze (avançado) — Nominalização para registro formal (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"The ___ of the architecture is what distinguishes a designed footprint from an accidental one.","a":"deliberateness"},
   {"q":"The ___ of the business in the structure is what makes it defensible under challenge.","a":"reflection"},
   {"q":"The ___ of an entity in a given jurisdiction must follow substance, not convenience.","a":"location / basing"},
   {"q":"The ___ of value across the group should mirror where the work is genuinely done.","a":"flow"},
   {"q":"The ___ of risk by each entity must correspond to the reward it is allocated.","a":"assumption / bearing"},
   {"q":"The ___ of a legacy structure is often costlier than its original construction.","a":"unwinding"},
   {"q":"The ___ of the footprint to the underlying business is the test an authority applies.","a":"correspondence / alignment"},
   {"q":"The ___ of the architecture over decades demands stability rather than constant change.","a":"endurance / stability"},
   {"q":"The ___ of a newspaper article should never dictate the design of a tax structure.","a":"publication / appearance"},
   {"q":"The ___ of each choice must be documented so the whole can be defended as deliberate.","a":"justification / rationale"}]},
 {"title":"Key word transformation — mantenha o sentido (nominalização)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"The architecture is deliberate, and that matters.  ·  (DELIBERATENESS)  ·  The ___ matters.","a":"deliberateness of the architecture"},
   {"q":"The structure reflects the business.  ·  (REFLECTION)  ·  The ___ makes it defensible.","a":"reflection of the business"},
   {"q":"We base the entity where the substance is.  ·  (LOCATION)  ·  The ___ follows substance.","a":"location of the entity"},
   {"q":"Each entity bears risk in line with its reward.  ·  (ASSUMPTION)  ·  The ___ matches the reward.","a":"assumption of risk"},
   {"q":"Unwinding the structure was costly.  ·  (UNWINDING)  ·  The ___ proved costly.","a":"unwinding of the structure"},
   {"q":"Value flows across the group in a certain way.  ·  (FLOW)  ·  The ___ mirrors the work done.","a":"flow of value"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (nominalização)","note":"Reescreva em registro formal usando nominalização.","items":[
   {"q":"The structure was designed on purpose, and that's the point.","a":"The deliberateness of the structure is precisely what renders it defensible."},
   {"q":"Where we put an entity has to follow where the real work happens.","a":"The location of an entity must follow the substance of the work performed."},
   {"q":"Each company should carry risk in proportion to what it earns.","a":"The assumption of risk by each entity must correspond to the reward it is allocated."},
   {"q":"Taking apart an old structure costs more than building it did.","a":"The unwinding of a legacy structure frequently exceeds the cost of its original construction."},
   {"q":"What an authority checks is whether the structure matches the business.","a":"What an authority tests is the correspondence of the footprint to the underlying business."},
   {"q":"You shouldn't design a structure around how it might look in the press.","a":"The design of a structure must never be dictated by the prospect of its appearance in the press."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (nominalização)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"The deliberate of the architecture makes it defensible.","a":"The deliberateness of the architecture makes it defensible. (nominalize o adjetivo: 'deliberateness')"},
   {"q":"The reflection of the business in the structure are defensible.","a":"The reflection of the business in the structure is defensible. (núcleo singular → 'is')"},
   {"q":"The location of the entity must follows substance.","a":"The location of the entity must follow substance. (após 'must', forma base 'follow')"},
   {"q":"The unwind of the structure proved costly.","a":"The unwinding of the structure proved costly. (substantivo formal é 'unwinding', não 'the unwind')"},
   {"q":"The assumption of risk by each entity must correspond the reward.","a":"The assumption of risk by each entity must correspond to the reward. ('correspond to')"},
   {"q":"The flow of value across the group mirror the work.","a":"The flow of value across the group mirrors the work. (núcleo singular → 'mirrors')"}]},
 {"title":"Advanced collocations & lexis — arquitetura tributária global (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"a global tax footprint","a":"uma pegada tributária global"},{"q":"to base an entity on substance","a":"sediar uma entidade com substância"},
   {"q":"to align reward with risk","a":"alinhar recompensa e risco"},{"q":"to unwind a legacy structure","a":"desfazer uma estrutura legada"},
   {"q":"a defensible architecture","a":"uma arquitetura defensável"},{"q":"to withstand the front page","a":"resistir à primeira página"},
   {"q":"substance over convenience","a":"substância sobre conveniência"},{"q":"to engineer a structure","a":"engendrar uma estrutura"},
   {"q":"a deliberate design choice","a":"uma escolha de desenho deliberada"},{"q":"to mirror the value chain","a":"espelhar a cadeia de valor"}]},
 {"title":"Discuss / Argue — nominalização no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"What distinguishes a defensible tax architecture from an accidental one?","a":"What distinguishes the two is the deliberateness of the design: a defensible footprint is one in which the location of every entity reflects the substance of the work performed."},
   {"q":"How should the location of an entity be decided?","a":"The location of an entity must follow the substance of its activity, since any divergence between the structure and the underlying business invites precisely the challenge we seek to avoid."},
   {"q":"Why must reward and risk be aligned across the group?","a":"The assumption of risk by each entity should correspond to the reward it is allocated, for it is the misalignment of the two that authorities scrutinise most keenly."},
   {"q":"What makes unwinding a legacy structure so costly?","a":"The unwinding of a legacy structure frequently exceeds the cost of its construction, which is itself the strongest argument for designing with stability and substance from the outset."},
   {"q":"How do you guard against designing for appearances?","a":"The design of a structure must never be governed by its prospective appearance in the press; rather, it should be governed by the reflection of the genuine business within it."},
   {"q":"What test do you apply to your own global footprint?","a":"The test I apply is correspondence: does the architecture mirror the value chain so faithfully that its every choice could be defended as deliberate and substantive?"}]}
]

