data["477"] = [
 {"title":"Open cloze (avançado) — Passado hipotético (fiscal-taxes)","note":"Sem opções. O aluno produz o elemento que falta.","items":[
   {"q":"Had we ___ the treaty position in advance, the exposure would have looked very different.","a":"modelled"},
   {"q":"Had the treaty been renegotiated, our relief ___ have been materially reduced.","a":"would"},
   {"q":"Had we relied solely on domestic relief, we ___ have been exposed to double taxation.","a":"would"},
   {"q":"The structure would have held ___ the political relationship not deteriorated.","a":"had"},
   {"q":"Had the forecast been modelled, the renegotiation risk ___ have been priced in.","a":"would"},
   {"q":"We could ___ claimed treaty relief had the residence test been satisfied.","a":"have"},
   {"q":"___ we anticipated the treaty change, we would have restructured a year earlier.","a":"Had"},
   {"q":"Had the relationship evolved differently, the favourable rate ___ have endured.","a":"might"},
   {"q":"The double-tax charge would not have arisen ___ the credit been claimed in time.","a":"had"},
   {"q":"Had we treated the treaty as a weather forecast, we ___ have hedged the political risk.","a":"would"}]},
 {"title":"Key word transformation — mantenha o sentido (passado hipotético)","note":"Reescreva usando a palavra-chave (3–6 palavras).","items":[
   {"q":"We didn't model the position, so the exposure surprised us.  ·  (HAD)  ·  ___ the position, the exposure would not have surprised us.","a":"Had we modelled"},
   {"q":"Because the treaty changed, our relief was reduced.  ·  (WOULD)  ·  Had the treaty held, our relief ___.","a":"would have been preserved"},
   {"q":"We relied on domestic relief and got exposed to double tax.  ·  (TREATY)  ·  Had we relied on the ___, we would not have been exposed.","a":"treaty relief instead"},
   {"q":"The political relationship soured, so the rate didn't last.  ·  (HAD)  ·  ___ soured, the rate would have endured.","a":"Had the relationship not"},
   {"q":"We could have claimed relief, but we missed the residence test.  ·  (SATISFIED)  ·  Had the residence test ___, we could have claimed relief.","a":"been satisfied"},
   {"q":"We didn't anticipate the change, so we restructured late.  ·  (ANTICIPATED)  ·  Had we ___ the change, we would have restructured earlier.","a":"anticipated"}]},
 {"title":"Register / paraphrase — eleve ao registro executivo (passado hipotético)","note":"Reescreva em registro formal usando passado hipotético.","items":[
   {"q":"If we'd modelled the treaty position, the exposure would've looked different.","a":"Had we modelled the treaty position in advance, the exposure would have appeared materially different."},
   {"q":"We leaned on domestic relief and ended up double-taxed.","a":"Had we relied on treaty relief rather than domestic provisions, we would not have been exposed to double taxation."},
   {"q":"The rate didn't last because the relationship went bad.","a":"Had the political relationship not deteriorated, the favourable rate would, in all likelihood, have endured."},
   {"q":"We missed the residence test, so we couldn't claim relief.","a":"Had the residence test been satisfied, we could have claimed treaty relief."},
   {"q":"We should have treated the treaty like a forecast and hedged.","a":"Had we treated the treaty as a weather forecast, we would have hedged the attendant political risk."},
   {"q":"If we'd seen the renegotiation coming, we'd have moved a year earlier.","a":"Had we anticipated the renegotiation, we would have restructured a full year earlier."}]},
 {"title":"Error correction (editing) — ache e corrija o erro sutil (passado hipotético)","note":"Um erro de C1/C2 por frase. Corrija e diga por quê.","items":[
   {"q":"If we would have modelled it, the exposure would have differed.","a":"Had we modelled it, the exposure would have differed. (oração condicional não usa 'would have')"},
   {"q":"Had we modelled the position, the exposure would looked different.","a":"Had we modelled the position, the exposure would have looked different. (resultado: 'would have' + particípio)"},
   {"q":"Had the residence test satisfied, we could have claimed relief.","a":"Had the residence test been satisfied, we could have claimed relief. (passiva exige 'been')"},
   {"q":"The rate would have endure had the relationship held.","a":"The rate would have endured had the relationship held. (particípio: 'endured')"},
   {"q":"Had we relied on treaty relief, we wouldn't been exposed.","a":"Had we relied on treaty relief, we would not have been exposed. ('would not have been')"},
   {"q":"We could of claimed relief had the test been met.","a":"We could have claimed relief had the test been met. ('could have', não 'could of')"}]},
 {"title":"Advanced collocations & lexis — dupla tributação e tratados (além da aula)","note":"Peça uma frase de registro formal com cada item.","items":[
   {"q":"to claim treaty relief","a":"pleitear benefício de tratado"},{"q":"to be exposed to double taxation","a":"ficar exposto à dupla tributação"},
   {"q":"to satisfy a residence test","a":"atender ao teste de residência"},{"q":"to model a treaty position","a":"modelar uma posição de tratado"},
   {"q":"a withholding tax leakage","a":"um vazamento de imposto na fonte"},{"q":"to renegotiate a treaty","a":"renegociar um tratado"},
   {"q":"a permanent establishment risk","a":"risco de estabelecimento permanente"},{"q":"to price in political risk","a":"precificar o risco político"},
   {"q":"a tie-breaker provision","a":"uma cláusula de desempate"},{"q":"to forecast treaty drift","a":"prever a deriva de tratados"}]},
 {"title":"Discuss / Argue — passado hipotético no seu trabalho","note":"Respostas-modelo C1–C2 que o aluno adapta.","items":[
   {"q":"How should treaties be used as strategic instruments?","a":"Had we treated treaties as static, we would have been blindsided by renegotiation; instead, I model them as evolving instruments whose political durability must itself be forecast."},
   {"q":"Describe an exposure that better modelling would have averted.","a":"Had we modelled the treaty position in advance, the withholding leakage that later surfaced would have been priced in and, in all probability, structured around."},
   {"q":"Why not rely solely on domestic relief?","a":"Had we relied on domestic relief alone, we would have remained exposed to double taxation, whereas a well-chosen treaty position would have eliminated the charge entirely."},
   {"q":"How does political risk bear on treaty strategy?","a":"Had the political relationship not deteriorated, the favourable rate would have endured; the episode taught me to treat every treaty as a weather forecast rather than a guarantee."},
   {"q":"What is the cost of missing a residence or eligibility test?","a":"Had the residence test been satisfied, we could have claimed relief in full, so we now verify eligibility before, not after, the transaction is structured."},
   {"q":"How do you build foresight into treaty planning?","a":"Had we anticipated the renegotiation, we would have restructured a year earlier, which is precisely why I now build treaty-drift scenarios into every long-horizon plan."}]}
]

